import React from 'react';
import Item from './Item'; // Fix: import Item component, not the CSS
import './Languages.css';

const Languages = () => {
  const language = [
    {
        title: "Python",
        logo: "https://upload.wikimedia.org/wikipedia/commons/c/c3/Python-logo-notext.svg" ,
    },
    {
        title: "JavaScript",
        logo: "https://upload.wikimedia.org/wikipedia/commons/6/69/JavaScript-logo.png"
    },
  ];

  return (
    <div className="languages-container"> {/* Add a wrapper class for the container */}
      {language.map((lang) => (
        <Item
          key={lang.title} // Always add a key for list items
          title={lang.title}
          logo={lang.logo}
        />
      ))}
    </div>
  );
};

export default Languages;
